156	        version: "1.5.0",
157	        name: "useImportType",
158	        language: "ts",
159	        sources: &[RuleSource::EslintTypeScript("consistent-type-imports").inspired()],
160	        recommended: true,
161	        severity: Severity::Warning,
162	        fix_kind: FixKind::Safe,
163	    }
164	}
